'use strict'

import resource from '../../resource'
import { DIRECTION_EAST, DIRECTION_WEST } from '../../constant'
import { drawImage } from './common'
import { Walker } from './walker'

// The ghost of the graveyard (object $21), measured in the ROM: it walks on the grid like an octorok, at
// random and stopped by the scenery, without shooting, and takes many hits. It only has a left and a right side
class Ghini extends Walker {
  constructor (type, x, y, direction, random = Math.random) {
    super(type, x, y, direction, random)
    this.facing = direction === DIRECTION_WEST ? DIRECTION_WEST : DIRECTION_EAST
  }

  act (map, link) {
    super.act(map, link)
    if (this.direction === DIRECTION_EAST || this.direction === DIRECTION_WEST) {
      this.facing = this.direction
    }
  }

  drawBody (context) {
    drawImage(context, resource.getSprite(`ghini_${this.facing}_move`), 0, this.x, this.y, this.width, this.height)
  }
}

export { Ghini }
